  whiteLabelingSettings(
    organizationId: "@td(WL_ELECTRONICS.id)"
    storeId: "@td(STORE_PRIMARY.id)"
    cultureName: "en-US"
  ) {
    footerLinks { title url priority childItems { title url priority } }
    mainMenuLinks { title url priority childItems { title url priority } }
  }
}
[ASSERT] 3. Verify response structure and hierarchy

